mapper.select:
select mi.id, md.id as detailId, mi.code, mi.work_type as workType, mi.approve_status as approveStatus, mi.invalid_status as invalidStatus, md.sku_id as skuId, md.sku_no as skuNo, mi.bill_date as billDate, md.qty, md.unit, mi.warehouse_name as warehouseName, md.remark, mi.approve_user_name as approveUserName, mi.approve_time as approveTime, mi.create_user_name as createUserName, mi.create_time as createTime, md.warehouse_location as warehouseLocation, mi.source_code as sourceCode, mi.source_id as sourceId, mi.source_type as sourceType from machine_info mi inner join machine_detail md on mi.id = md.main_id and md.is_deleted = false where ${params.sqlMap.default} and mi.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
mi.id desc,md.id asc

select count(distinct mi.id) from machine_info mi left join machine_detail md on mi.id = md.main_id and md.is_deleted = false
${params.sqlMap.default} and mi.is_deleted = false
${params.permissionSql}

select mi.id, mi.code, mi.work_type as workType, mi.approve_status as approveStatus, mi.invalid_status as invalidStatus, md.sku_id as skuId, md.sku_no as skuNo, mi.bill_date as billDate, md.qty, md.unit, mi.warehouse_name as warehouseName, md.warehouse_location as warehouseLocation, md.remark, mi.approve_user_name as approveUserName, mi.approve_time as approveTime, mi.create_user_name as createUserName, mi.create_time as createTime, mi.source_code as sourceCode, mi.source_id as sourceId, mi.source_type as sourceType from machine_info mi inner join machine_detail md on mi.id = md.main_id and md.is_deleted = false where ${params.sqlMap.default} and mi.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
mi.id desc,md.id desc
